mapper.update:
update cs_retain_details set
  branch_key = #{dto.branchKey, jdbcType=VARCHAR},
  target_branch_key = #{dto.targetBranchKey, jdbcType=VARCHAR}
where branch_uuid = #{dto.branchUuid, jdbcType=VARCHAR}

mapper.select:
select t.issue_kee
from cs_issue_track_for_retain t
where
  t.retained_status = #{retainedStatus, jdbcType=VARCHAR}
  and t.issue_kee in

    #{issueKey, jdbcType=VARCHAR}

mapper.delete:
delete from cs_issue_track_for_retain
where
  retained_status = #{retainedStatus, jdbcType=VARCHAR}
  and issue_kee in

    #{issueKey, jdbcType=VARCHAR}

mapper.select:
select

from cs_issue_track_for_retain t
inner join cs_retain_details d on d.branch_uuid = t.branch_uuid
where
  d.project_uuid = #{projectUuid, jdbcType=VARCHAR}
  and t.retained_status = #{retainedStatus, jdbcType=VARCHAR}

    and t.branch_uuid in

      #{branchUuid, jdbcType=VARCHAR}


order by t.fixed_at, t.uuid

mapper.insert:
insert into cs_retain_issue_comments ( uuid, issue_kee, change_data, user_uuid, issue_change_creation_date ) select ic.uuid, ic.issue_key, ic.change_data, ic.user_login, ic.issue_change_creation_date from issue_changes ic where ic.change_type = 'comment' and ic.issue_key in
#{issueKey, jdbcType=VARCHAR}
and exists (select 1 from cs_issue_track_for_retain t where t.issue_kee = ic.issue_key) and not exists (select 1 from cs_retain_issue_comments c where c.uuid = ic.uuid)

mapper.select:
select c.uuid as "uuid", c.issue_kee as "issueKey", c.change_data as "changeData", c.user_uuid as "userUuid", c.issue_change_creation_date as "issueChangeCreationDate" from cs_retain_issue_comments c where c.issue_kee in
#{issueKey, jdbcType=VARCHAR}
order by c.issue_kee, c.issue_change_creation_date, c.uuid

mapper.delete:
delete from cs_issue_track_for_retain
where branch_uuid in (
  select d.branch_uuid
  from cs_retain_details d
  where d.project_uuid = #{projectUuid, jdbcType=VARCHAR}
)
